import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Enumeration: DamageCause","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/enumerations/DamageCause.md","filePath":"api/@jsprismarine/prismarine/enumerations/DamageCause.md"}`),a={name:`api/@jsprismarine/prismarine/enumerations/DamageCause.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / DamageCause</p><h1 id="enumeration-damagecause" tabindex="-1">Enumeration: DamageCause <a class="header-anchor" href="#enumeration-damagecause" aria-label="Permalink to “Enumeration: DamageCause”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L10" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:10</a></p><p>What hurt an entity. Carried through so a death can be reported as what it was, and so the things that ignore particular kinds of damage have something to test.</p><p>Its own file rather than a member of <code>Entity</code>, because <code>DamageSource</code> has to name both this and <code>Entity</code>, and <code>Entity</code> has to name <code>DamageSource</code> - which is the runtime cycle the import rules in <code>biome.json</code> exist to prevent. <code>Entity</code> re-exports it, so the older <code>import { DamageCause } from &#39;./entity/Entity&#39;</code> still resolves and nothing had to be rewritten.</p><h2 id="enumeration-members" tabindex="-1">Enumeration Members <a class="header-anchor" href="#enumeration-members" aria-label="Permalink to “Enumeration Members”">​</a></h2><h3 id="attack" tabindex="-1">Attack <a class="header-anchor" href="#attack" aria-label="Permalink to “Attack”">​</a></h3><blockquote><p><strong>Attack</strong>: <code>&quot;attack&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L21" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:21</a></p><p>Struck by something holding a weapon, or a fist.</p><hr><h3 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h3><blockquote><p><strong>Contact</strong>: <code>&quot;contact&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L26" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:26</a></p><p>Walked into something that hurts to touch: a cactus, a berry bush.</p><hr><h3 id="drowning" tabindex="-1">Drowning <a class="header-anchor" href="#drowning" aria-label="Permalink to “Drowning”">​</a></h3><blockquote><p><strong>Drowning</strong>: <code>&quot;drowning&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L12" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:12</a></p><hr><h3 id="explosion" tabindex="-1">Explosion <a class="header-anchor" href="#explosion" aria-label="Permalink to “Explosion”">​</a></h3><blockquote><p><strong>Explosion</strong>: <code>&quot;explosion&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L24" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:24</a></p><hr><h3 id="fall" tabindex="-1">Fall <a class="header-anchor" href="#fall" aria-label="Permalink to “Fall”">​</a></h3><blockquote><p><strong>Fall</strong>: <code>&quot;fall&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L14" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:14</a></p><hr><h3 id="fire" tabindex="-1">Fire <a class="header-anchor" href="#fire" aria-label="Permalink to “Fire”">​</a></h3><blockquote><p><strong>Fire</strong>: <code>&quot;fire&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L16" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:16</a></p><p>Standing in flames, or burning after having stood in them.</p><hr><h3 id="generic" tabindex="-1">Generic <a class="header-anchor" href="#generic" aria-label="Permalink to “Generic”">​</a></h3><blockquote><p><strong>Generic</strong>: <code>&quot;generic&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L11" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:11</a></p><hr><h3 id="lava" tabindex="-1">Lava <a class="header-anchor" href="#lava" aria-label="Permalink to “Lava”">​</a></h3><blockquote><p><strong>Lava</strong>: <code>&quot;lava&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L18" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:18</a></p><p>In the lava itself, which hurts far faster than the fire it leaves behind.</p><hr><h3 id="magic" tabindex="-1">Magic <a class="header-anchor" href="#magic" aria-label="Permalink to “Magic”">​</a></h3><blockquote><p><strong>Magic</strong>: <code>&quot;magic&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L30" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:30</a></p><p>Potions and the like, which armor does nothing about.</p><hr><h3 id="projectile" tabindex="-1">Projectile <a class="header-anchor" href="#projectile" aria-label="Permalink to “Projectile”">​</a></h3><blockquote><p><strong>Projectile</strong>: <code>&quot;projectile&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L23" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:23</a></p><p>Hit by something thrown or fired, which is not the same as being struck by its owner.</p><hr><h3 id="starvation" tabindex="-1">Starvation <a class="header-anchor" href="#starvation" aria-label="Permalink to “Starvation”">​</a></h3><blockquote><p><strong>Starvation</strong>: <code>&quot;starvation&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L13" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:13</a></p><hr><h3 id="suffocation" tabindex="-1">Suffocation <a class="header-anchor" href="#suffocation" aria-label="Permalink to “Suffocation”">​</a></h3><blockquote><p><strong>Suffocation</strong>: <code>&quot;suffocation&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L28" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:28</a></p><p>A solid block where the entity&#39;s head is.</p><hr><h3 id="thorns" tabindex="-1">Thorns <a class="header-anchor" href="#thorns" aria-label="Permalink to “Thorns”">​</a></h3><blockquote><p><strong>Thorns</strong>: <code>&quot;thorns&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L33" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:33</a></p><p>Reflected back at an attacker by the armor they hit.</p><hr><h3 id="void" tabindex="-1">Void <a class="header-anchor" href="#void" aria-label="Permalink to “Void”">​</a></h3><blockquote><p><strong>Void</strong>: <code>&quot;void&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L19" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:19</a></p><hr><h3 id="wither" tabindex="-1">Wither <a class="header-anchor" href="#wither" aria-label="Permalink to “Wither”">​</a></h3><blockquote><p><strong>Wither</strong>: <code>&quot;wither&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/entity/DamageCause.ts#L31" target="_blank" rel="noreferrer">packages/prismarine/src/entity/DamageCause.ts:31</a></p>`,73)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};